import { test, expect } from '@playwright/test';

test.describe('Unsaved Form Warning', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display warning when user attempts to navigate away from unsaved form', async ({ page }) => {
    // Fill form fields using getByLabel
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('john@example.com');

    // Submit form using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Attempt to navigate away using getByRole
    const backButton = page.getByRole('button', { name: /back/i });
    await backButton.click();

    // Verify warning message appears
    const warningMessage = page.getByText('You have unsaved changes');
    await expect(warningMessage).toBeVisible();

    // Verify navigation is blocked
    const navigationLink = page.getByRole('link', { name: /cancel/i });
    await expect(navigationLink).toBeDisabled();

    // Verify form fields are still filled
    await expect(nameInput).toHaveValue('John Doe');
    await expect(emailInput).toHaveValue('john@example.com');

    // Verify warning message is still visible
    await expect(warningMessage).toBeVisible();
  });

  test('should clear warning when form is saved', async ({ page }) => {
    // Fill form fields using getByLabel
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('Jane Smith');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('jane@example.com');

    // Submit form using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify warning message is gone
    const warningMessage = page.getByText('You have unsaved changes');
    await expect(warningMessage).not.toBeVisible();

    // Verify navigation is enabled
    const navigationLink = page.getByRole('link', { name: /cancel/i });
    await expect(navigationLink).not.toBeDisabled();

    // Verify form fields are still filled
    await expect(nameInput).toHaveValue('Jane Smith');
    await expect(emailInput).toHaveValue('jane@example.com');

    // Verify warning message is not visible
    await expect(warningMessage).not.toBeVisible();
  });
});
